import sys

MOD = 998244353

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    k = int(data[1])
    if k >= n:
        print(0)
        return
    c = n - k
    maxN = n
    fact = [1] * (maxN + 1)
    for i in range(1, maxN + 1):
        fact[i] = fact[i-1] * i % MOD
    inv_fact = [1] * (maxN + 1)
    inv_fact[maxN] = pow(fact[maxN], MOD-2, MOD)
    for i in range(maxN, 0, -1):
        inv_fact[i-1] = inv_fact[i] * i % MOD
    def comb(n, k):
        if k < 0 or k > n:
            return 0
        return fact[n] * inv_fact[k] % MOD * inv_fact[n-k] % MOD
    ans = 0
    for a in range(1, c+1):
        x = pow(a, n, MOD) * comb(c, a) % MOD
        if (c - a) % 2 == 0:
            ans = (ans + x) % MOD
        else:
            ans = (ans - x) % MOD
    ans = ans * comb(n, c) % MOD
    if k > 0:
        ans = ans * 2 % MOD
    print(ans)

if __name__ == "__main__":
    solve()

