            return 0
        return fact[nn] * inv_fact[kk] % MOD * inv_fact[nn - kk] % MOD

    ans = 0
    for a in range(1, c + 1):
        x = pow(a, n, MOD) * comb(c, a) % MOD
        if (c - a) % 2 == 0:
            ans = (ans + x) % MOD
        else:
            ans = (ans - x) % MOD

    ans %= MOD
    if ans < 0:
        ans += MOD

    ans = ans * comb(n, c) % MOD
    if k > 0:
        ans = ans * 2 % MOD

    print(ans)

